import{_ as a,o as e,c as s,ai as d}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"AI 软件工程 SOP：从项目接入到持续交付","description":"","frontmatter":{},"headers":[],"relativePath":"ai/sop/index.md","filePath":"ai/sop/index.md"}'),r={name:"ai/sop/index.md"};function i(o,t,l,n,h,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="ai-软件工程-sop-从项目接入到持续交付" tabindex="-1">AI 软件工程 SOP：从项目接入到持续交付 <a class="header-anchor" href="#ai-软件工程-sop-从项目接入到持续交付" aria-label="Permalink to “AI 软件工程 SOP：从项目接入到持续交付”">​</a></h1><blockquote><p><strong>AI Software Engineering SOP · V1.0</strong> 一套面向 AI Agent 的通用软件工程标准作业体系 —— 让开发者面对新项目或老项目时，都能用同一套标准化流程完成项目认知、环境准备、AI 协作体系建设、任务执行、质量验收和经验沉淀。</p></blockquote><h2 id="这套-sop-解决什么" tabindex="-1">这套 SOP 解决什么 <a class="header-anchor" href="#这套-sop-解决什么" aria-label="Permalink to “这套 SOP 解决什么”">​</a></h2><p>用 AI 写代码一段时间后，真正费时间的不再是敲代码，而是这些事：</p><ul><li>每次开新会话都要重新解释技术栈、目录、禁改区、构建命令；</li><li>换一个 AI 编程工具，之前攒的配置几乎全部作废；</li><li>AI 说「已完成」，但没人能说清「完成」到底指什么；</li><li>项目里踩过的坑只存在聊天记录里，下一个项目重新踩一遍。</li></ul><p>它的定位是<strong>方法论，不是工具教程</strong>。Cursor、WorkBuddy、Claude Code 只是执行工具，真正可迁移的是这套开发方法本身。所以这里不写任何工具的按钮和目录约定，具体落地办法单独放在工具适配层。</p><div class="tip custom-block"><p class="custom-block-title">核心原则</p><p>学习和理解是基础，项目实践是验证，通用方法论是最终沉淀。不能为了追求自动化，牺牲开发者对业务、架构和代码的理解。</p></div><h2 id="四阶段总览" tabindex="-1">四阶段总览 <a class="header-anchor" href="#四阶段总览" aria-label="Permalink to “四阶段总览”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 项目初始化          02 AI 协作体系          03 标准开发流程        04 持续改进</span></span>
<span class="line"><span>项目扫描、认知与建档 ─→ Rules / Agents ─────→ 需求 → 设计 → 开发 ─→ 经验沉淀、复盘</span></span>
<span class="line"><span>新项目 / 老项目双入口    Skills / MCP / Hooks   测试 → Review → 交付    规则迭代、版本升级</span></span>
<span class="line"><span>        │                      │                      │                    │</span></span>
<span class="line"><span>        └──────────────────────┴──────────────────────┴────────────────────┘</span></span>
<span class="line"><span>                    每一轮迭代结束后回到「持续改进」，再进入下一轮主链</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>新项目和老项目<strong>入口不同、主链相同</strong>：前者先定边界再建体系，后者先扫描理解再逐步接入，汇合点是《项目认知报告》，之后走完全一样的开发流程。</p><h2 id="八章地图" tabindex="-1">八章地图 <a class="header-anchor" href="#八章地图" aria-label="Permalink to “八章地图”">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>章节</th><th>解决什么</th><th>状态</th></tr></thead><tbody><tr><td>01</td><td><a href="/my-vitepress-site/ai/sop/01-methodology.html">方法论与总体架构</a></td><td>三层架构、五个协作机制的职责边界、人机分工、完整流程图</td><td><strong>V1.0 · 已交付</strong></td></tr><tr><td>02</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">项目接入与初始化</a></td><td>新/老项目双流程、项目认知报告、扫描 Prompt、接入验收</td><td><strong>V1.0 · 已交付</strong></td></tr><tr><td>03</td><td><a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">AI 协作体系建设</a></td><td>Rules / Agent / Skills / MCP / Hooks 的建法与模板</td><td><strong>V1.0 · 已交付</strong></td></tr><tr><td>04</td><td>需求分析与技术设计</td><td>需求澄清、业务规则、数据模型、API 契约、任务拆分</td><td>M2 规划</td></tr><tr><td>05</td><td>AI 驱动软件开发</td><td>任务拆解、并行与串行、上下文传递、阶段性验收</td><td>M2 规划</td></tr><tr><td>06</td><td>测试与质量保障</td><td>单测到 E2E、代码审查、构建验证、完成标准</td><td>M2 规划</td></tr><tr><td>07</td><td>项目交付与维护</td><td>文档同步、部署发布、版本、问题追踪、交付报告</td><td>M2 规划</td></tr><tr><td>08</td><td>持续优化与能力沉淀</td><td>根因分析、沉淀位置判断、复用验证、通用库版本管理</td><td>M2 规划</td></tr></tbody></table><p>M2、M3 的章节当前只在目录中占位，<strong>不提供链接</strong>，避免指向尚不存在的页面。</p><h2 id="怎么用-四条路径" tabindex="-1">怎么用：四条路径 <a class="header-anchor" href="#怎么用-四条路径" aria-label="Permalink to “怎么用：四条路径”">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>从哪开始</th><th>先拿到什么</th></tr></thead><tbody><tr><td>启动一个全新项目</td><td><a href="/my-vitepress-site/ai/sop/01-methodology.html">01</a> → <a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 新项目 SOP</a> → <a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 最小集</a></td><td>目标边界 + 项目认知报告 + 一份全局 Rules</td></tr><tr><td>接手一个已有仓库</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 老项目 SOP</a>（含扫描 Prompt 与禁令）→ <a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03</a></td><td>事实/待确认分离的认知报告，且不做架构改动</td></tr><tr><td>只想拿一份能用的模板</td><td>直接跳到下方「可复制模板」</td><td>报告、Rules、Agent、Skill 四份完整模板</td></tr><tr><td>想先搞清方法再动手</td><td><a href="/my-vitepress-site/ai/sop/01-methodology.html">01 方法论</a> 全篇</td><td>三层架构 + 五机制职责表</td></tr></tbody></table><h2 id="三层边界-别把工具当方法" tabindex="-1">三层边界：别把工具当方法 <a class="header-anchor" href="#三层边界-别把工具当方法" aria-label="Permalink to “三层边界：别把工具当方法”">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>会随什么变化</th></tr></thead><tbody><tr><td>通用方法层</td><td>项目认知、需求、架构、Rules/Agent/Skill 设计、开发流程、测试验收、复盘</td><td>基本不变</td></tr><tr><td>工具适配层</td><td>具体工具的目录名、配置语法、调用方式、能力边界</td><td>工具版本</td></tr><tr><td>项目特定层</td><td>业务规则、数据表、接口契约、历史决策、gotchas</td><td>每个仓库</td></tr></tbody></table><p>判断准则：<strong>一段内容如果换个 AI 工具就得重写，说明它写错了层。</strong> 因此本 SOP 涉及具体工具功能时，一律以对应版本官方文档为准，不把某个工具的目录结构当成行业通用规范，也不编造未经验证的特性。</p><h2 id="可复制资产清单" tabindex="-1">可复制资产清单 <a class="header-anchor" href="#可复制资产清单" aria-label="Permalink to “可复制资产清单”">​</a></h2><p>按最初的交付物清单逐项标注，未完成的如实列出，不虚报。</p><h3 id="v1-0-·-m1-已交付" tabindex="-1">V1.0 · M1 已交付 <a class="header-anchor" href="#v1-0-·-m1-已交付" aria-label="Permalink to “V1.0 · M1 已交付”">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>资产</th><th>位置</th></tr></thead><tbody><tr><td>1</td><td>SOP 总体架构图（三层）</td><td><a href="/my-vitepress-site/ai/sop/01-methodology.html">01 章第三节</a></td></tr><tr><td>2</td><td>新项目接入流程图</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 章第一节</a></td></tr><tr><td>3</td><td>老项目接入流程图</td><td>同上（同一张双入口图）</td></tr><tr><td>4</td><td>AI 协作体系职责架构（表格图）</td><td><a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 章全篇</a></td></tr><tr><td>5</td><td>完整开发生命周期流程图（简版）</td><td><a href="/my-vitepress-site/ai/sop/01-methodology.html">01 章第六节</a></td></tr><tr><td>6</td><td><strong>Rules 编写模板</strong> + 填好的全局规则示例</td><td><a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 章第一节</a></td></tr><tr><td>7</td><td><strong>Agent 编写模板</strong> + 填好的 Reviewer 示例</td><td><a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 章第二节</a></td></tr><tr><td>8</td><td><strong>Skill 编写模板</strong> + 填好的局部改动示例</td><td><a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 章第三节</a></td></tr><tr><td>9</td><td><strong>《项目认知报告》模板</strong> + WMS 填写示例</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 章第五节</a></td></tr><tr><td>—</td><td>项目目录模板（与工具无关）</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 章第六节</a></td></tr><tr><td>—</td><td>可复制 Prompt（老项目扫描 / 新项目澄清）</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 章第三节</a></td></tr><tr><td>—</td><td>接入验收清单 / 协作体系建设验收清单</td><td><a href="/my-vitepress-site/ai/sop/02-project-onboarding.html">02 章第七节</a>、<a href="/my-vitepress-site/ai/sop/03-collaboration-system.html">03 章第八节</a></td></tr><tr><td>—</td><td>版本记录与修订机制</td><td><a href="/my-vitepress-site/ai/sop/changelog.html">版本记录</a></td></tr></tbody></table><h3 id="m2-规划-完整开发流程-流程类模板" tabindex="-1">M2 规划（完整开发流程 + 流程类模板） <a class="header-anchor" href="#m2-规划-完整开发流程-流程类模板" aria-label="Permalink to “M2 规划（完整开发流程 + 流程类模板）”">​</a></h3><p>需求分析模板 · 技术设计模板 · 任务拆解模板 · 开发验收模板 · 测试报告模板 · 项目交付报告模板 · 阶段性复盘模板，以及第 04–08 章正文。</p><h3 id="m3-规划-工具适配" tabindex="-1">M3 规划（工具适配） <a class="header-anchor" href="#m3-规划-工具适配" aria-label="Permalink to “M3 规划（工具适配）”">​</a></h3><p>Cursor 工具适配指南 · WorkBuddy 工具适配指南 · 模板库独立页。</p><div class="warning custom-block"><p class="custom-block-title">关于 Mermaid</p><p>本站当前未启用 Mermaid 渲染插件，因此本栏目的架构图与流程图均使用<strong>文本流程图 + 表格图</strong>表达，零依赖、构建稳定，且与站内现有文章风格一致。若后续启用渲染插件，可平滑替换为矢量图，内容结构不需要改。</p></div><h2 id="怎么算「这套-sop-用起来了」" tabindex="-1">怎么算「这套 SOP 用起来了」 <a class="header-anchor" href="#怎么算「这套-sop-用起来了」" aria-label="Permalink to “怎么算「这套 SOP 用起来了」”">​</a></h2><p>不是看写了多少页，而是看这五条能不能在真实项目里打勾：</p><ul><li>[ ] 新开一轮会话时，不需要重新解释技术栈与禁改区（项目认知报告在仓库里）</li><li>[ ] 换一个 AI 编程工具，只改适配层，通用方法层原样复用</li><li>[ ] 每个任务有一份冻结的 Spec，开发和 Review 都对着它</li><li>[ ] 「完成」由人对照验收清单判定，有命令输出或 diff 作为证据</li><li>[ ] 重复出现的问题能被沉淀到明确位置，并在第二个项目里验证过</li></ul><h2 id="版本与迭代" tabindex="-1">版本与迭代 <a class="header-anchor" href="#版本与迭代" aria-label="Permalink to “版本与迭代”">​</a></h2><p>采用版本化管理，先把 <strong>V1.0 做到能独立使用</strong>，不追求大而全：V1.0 通用 SOP → V1.1 多 Agent 协作与任务调度 → V1.2 工业数字化项目开发规范 → V2.0 更成熟的 AI Agent 自动化开发体系。详见 <a href="/my-vitepress-site/ai/sop/changelog.html">版本记录与修订机制</a>。</p><p>后续会拿真实项目的开发过程来验证：<strong>哪一步不好用就改 SOP，哪种 Skill 反复有效就沉淀下来</strong>。这里展示的应当是实践、验证、迭代出来的方法，而不是一次写成的文章集合。</p><hr><p>配套：<a href="/my-vitepress-site/ai/productivity/ai-coding-workflow.html">AI 辅助编程工作流</a> · <a href="/my-vitepress-site/ai/productivity/tool-selection.html">AI 工具与选型</a> · <a href="/my-vitepress-site/ai/prompts/coding.html">提示词库 · 编程开发</a> · <a href="/my-vitepress-site/ai/">返回 AI 赋能与个人提效</a></p>`,35)])])}const b=a(r,[["render",i]]);export{c as __pageData,b as default};
